function loginStatus(message){var box=el('login-error');box.setAttribute('role','status');box.setAttribute('aria-live','polite');box.textContent=message;box.scrollIntoView({block:'center',behavior:'smooth'});}
function friendlyLoginError(e){var code=e.code||'',text=e.message||'';if(code==='over_email_send_rate_limit'||/email rate limit/i.test(text))return 'Kayıt hizmeti geçici olarak sınırlandı. Tekrar tekrar basma; yöneticine haber ver.';if(['over_request_rate_limit','over_user_request_rate_limit'].includes(code)||e.status===429)return 'Peş peşe çok fazla deneme yapıldı. Bir süre bekleyip yalnız bir kez tekrar dene.';if(code==='weak_password')return 'Daha güçlü, en az 8 karakterli bir şifre belirle.';if(code==='email_address_invalid')return 'E-posta adresini kontrol et.';if(/Failed to fetch|NetworkError|Load failed|fetch failed/i.test(text))return 'Bağlantı kurulamadı. İnternetini kontrol edip tekrar dene.';return text||'İşlem tamamlanamadı. Yöneticine haber ver.';}
async function loginRequest(work,message){if(window.MKSK_LOGIN_BUSY)return;window.MKSK_LOGIN_BUSY=true;var buttons=Array.from(el('login-form').querySelectorAll('button'));buttons.forEach(b=>b.disabled=true);el('login-error').classList.remove('login-success');loginStatus(message);var timer=setTimeout(()=>loginStatus('Bağlantı normalden uzun sürüyor. İşlem devam ediyor; tekrar basmana gerek yok.'),12000);try{await work();}catch(e){loginStatus(friendlyLoginError(e));}finally{clearTimeout(timer);window.MKSK_LOGIN_BUSY=false;buttons.forEach(b=>b.disabled=false);}}

function inviteLoginUi(){
var form=el('login-form'),emailInput=el('email'),passwordInput=el('password'),submit=form.querySelector('button[type=submit]'),note=document.createElement('p'),tabs=document.createElement('div'),heading=el('login-view').querySelector('h2');
submit.before(el('login-error'));note.className='simple-login-note';tabs.className='login-mode-tabs';tabs.setAttribute('role','group');tabs.setAttribute('aria-label','Hesap oluştur veya giriş yap');tabs.innerHTML='<button type="button" data-login-mode="signup">1 · HESAP OLUŞTUR</button><button type="button" data-login-mode="login">2 · GİRİŞ YAP</button>';form.prepend(note);form.prepend(tabs);
emailInput.autocomplete='username';emailInput.inputMode='email';emailInput.autocapitalize='none';emailInput.spellcheck=false;emailInput.placeholder='Kendi e-posta adresin';passwordInput.placeholder='Uygulama şifren';
var reveal=document.createElement('button');reveal.type='button';reveal.className='login-password-toggle';reveal.textContent='ŞİFREYİ GÖSTER';reveal.setAttribute('aria-controls',passwordInput.id);reveal.setAttribute('aria-pressed','false');reveal.onclick=()=>{var visible=passwordInput.type==='password';passwordInput.type=visible?'text':'password';reveal.textContent=visible?'ŞİFREYİ GİZLE':'ŞİFREYİ GÖSTER';reveal.setAttribute('aria-pressed',String(visible));};passwordInput.after(reveal);
var b=document.createElement('button');b.type='button';b.id='invite-signup-action';b.textContent='HESAP OLUŞTUR';form.appendChild(b);
var privacy=document.createElement('p');privacy.className='simple-login-privacy';privacy.textContent='Yalnız kendi hesabınla giriş yap. Giriş ve yaklaşık kullanım süren yönetim tarafından görülebilir.';form.appendChild(privacy);
function mode(key){var signup=key==='signup';form.dataset.loginMode=key;b.hidden=!signup;submit.hidden=signup;submit.textContent='GİRİŞ YAP';passwordInput.autocomplete=signup?'new-password':'current-password';passwordInput.minLength=signup?8:1;if(heading)heading.textContent=signup?'ÖNCE HESABINI OLUŞTUR':'MKSK HESABINA GİR';note.textContent=signup?(inviteToken?'E-postanı yaz, uygulama için en az 8 karakterli şifre belirle ve HESAP OLUŞTUR’a bas. E-posta veya SMS kodu bekleme. Hesabın zaten varsa GİRİŞ YAP’ı seç.':'Yeni kayıt için yöneticinin sana özel gönderdiği uygulama bağlantısını aç. Hesabın varsa GİRİŞ YAP’ı seç.'):'E-postanı ve uygulama şifreni yaz, GİRİŞ YAP’a bas. E-posta veya SMS kodu gerekmez.';tabs.querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',String(t.dataset.loginMode===key)));el('login-error').textContent='';el('login-error').classList.remove('login-success');}
b.onclick=()=>{if(!inviteToken){loginStatus('Kayıt için yöneticinin sana özel gönderdiği davet bağlantısını aç.');return;}var email=emailInput.value.trim(),password=passwordInput.value;emailInput.value=email;if(!email||!emailInput.checkValidity()){loginStatus('E-posta adresini kontrol et.');emailInput.focus();return;}if(password.length<8){loginStatus('En az 8 karakterli bir uygulama şifresi belirle. Gmail şifreni kullanman gerekmiyor.');passwordInput.focus();return;}
return loginRequest(async()=>{var r=await supabase.auth.signUp({email,password});if(r.error){if(['user_already_exists','email_exists'].includes(r.error.code)){mode('login');throw Error('Bu e-postayla hesabın zaten var. Yeni hesap açma; GİRİŞ YAP’a bas.');}throw r.error;}var identities=r.data.user&&r.data.user.identities;if(!r.data.session){mode('login');throw Error(Array.isArray(identities)&&identities.length===0?'Bu e-postayla hesabın zaten var. Uygulama şifrenle GİRİŞ YAP.':'Kayıt yanıtı tamamlanamadı. Yeniden hesap açmadan önce yöneticine haber ver.');}
var claimError=null;try{await claimInvite();}catch(err){claimError=err;}var out=await supabase.auth.signOut({scope:'local'});mode('login');if(claimError)throw Error('Hesabın oluştu, ancak oyuncu davetin eşleşmedi. Tekrar hesap oluşturma; yöneticinden yeni davet iste.');if(out.error)throw Error('Hesabın oluştu. Sayfayı yenileyip GİRİŞ YAP’ı seç.');emailInput.value=email;passwordInput.value=password;el('login-error').classList.add('login-success');loginStatus('HESABIN HAZIR ✓ Şimdi aşağıdaki GİRİŞ YAP düğmesine bas.');submit.focus();},'Hesabın oluşturuluyor… Bir kez basman yeterli.');};
tabs.querySelectorAll('button').forEach(t=>t.onclick=()=>mode(t.dataset.loginMode));mode(inviteToken?'signup':'login');}

async function accountTools(){document.querySelectorAll('.player-edit').forEach(f=>{var body=f.querySelector('.data-entry-body'),b=document.createElement('button'),result=document.createElement('div');b.type='button';b.textContent='Kişisel davet bağlantısı oluştur';b.onclick=async()=>{b.disabled=true;result.textContent='Davet hazırlanıyor...';var r=await supabase.rpc('create_player_invite',{target_player:f.dataset.id});if(r.error){result.textContent=r.error.message;b.disabled=false;return;}result.textContent='7 gün geçerli, tek kullanımlık. Yalnızca bu oyuncuya özelden gönder. Yeni davet eski kullanılmamış bağlantıyı iptal eder.';var input=document.createElement('input');input.readOnly=true;input.value=location.origin+location.pathname+'#davet='+encodeURIComponent(r.data);input.setAttribute('aria-label','Kişisel davet bağlantısı');var copy=document.createElement('button');copy.type='button';copy.textContent='Bağlantıyı kopyala';copy.onclick=async()=>{try{await navigator.clipboard.writeText(input.value);copy.textContent='Kopyalandı';}catch(e){input.select();copy.textContent='Bağlantıyı seçip kopyalayabilirsin';}};result.append(input,copy);b.disabled=false;};body.append(b,result);});var panel=el('visit-panel');if(!panel){panel=document.createElement('section');panel.id='visit-panel';panel.className='card';el('team-summary').after(panel);}panel.innerHTML='<h3>Oyuncu giriş geçmişi</h3><p>Giriş sayısı oturum açılışlarını gösterir; sayfa yenileme de yeni oturum sayılabilir. Süre yalnızca açık ve aktif sayfadan yaklaşık ölçülür.</p><button type="button">Giriş geçmişini yenile</button><div class="visit-results"></div>';panel.querySelector('button').onclick=async()=>{var box=panel.querySelector('.visit-results');if(panel.dataset.visitLoading==='true')return;panel.dataset.visitLoading='true';if(!box.children.length)box.textContent='Yükleniyor...';var r=await supabase.from('player_visit_sessions').select('player_id,started_at,last_seen,active_seconds').order('started_at',{ascending:false}).limit(5000);panel.dataset.visitLoading='false';if(r.error){var status=panel.querySelector('.visit-error');if(!status){status=document.createElement('p');status.className='visit-error';status.setAttribute('role','status');panel.prepend(status);}status.textContent='GÜNCELLENEMEDİ: '+r.error.message;return;}panel.querySelector('.visit-error')?.remove();var totals={};r.data.forEach(s=>{var a=totals[s.player_id]||(totals[s.player_id]={count:0,seconds:0,last:s.started_at});a.count++;a.seconds+=s.active_seconds;});var fragment=document.createDocumentFragment();document.querySelectorAll('.player-edit').forEach(f=>{var a=totals[f.dataset.id],p=document.createElement('article');p.className='visit-card';p.innerHTML='<div class="visit-card-title"><strong>'+safe(f.querySelector('[name=full_name]').value)+'</strong><span class="visit-count">'+(a?a.count:0)+' giriş</span></div><div class="visit-metrics"><div><span>Aktif kullanım</span><strong>'+(a?Math.floor(a.seconds/60)+' dk '+a.seconds%60+' sn':'—')+'</strong></div><div><span>Son giriş</span><strong>'+(a?safe(new Date(a.last).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'})):'Henüz giriş yok')+'</strong></div></div>';fragment.appendChild(p);});box.replaceChildren(fragment);};}
var visitId=null,visitTimer=null,lastActivity=Date.now();['pointerdown','keydown','scroll','touchstart'].forEach(event=>document.addEventListener(event,()=>lastActivity=Date.now(),{passive:true}));
async function trackVisit(){if(window.MKSK_PLAYER_PREVIEW||visitId)return;var r=await supabase.rpc('start_player_visit');if(r.error||!r.data)return;visitId=r.data;var notice=document.createElement('p');notice.textContent='Giriş sayısı, son giriş ve yaklaşık aktif kullanım süren yöneticiler tarafından görülebilir.';el('player-view').prepend(notice);visitTimer=setInterval(async()=>{var access=await supabase.rpc('player_access_allowed');if(!access.error&&!access.data){clearInterval(visitTimer);visitTimer=null;visitId=null;await supabase.auth.signOut();show('login-view');el('player-name').textContent='';el('player-summary').innerHTML='';el('player-stats').innerHTML='';if(el('player-report'))el('player-report').innerHTML='';el('login-error').textContent='Oyuncu erişiminiz yönetici tarafından kapatılmış.';return;}if(document.visibilityState==='visible'&&Date.now()-lastActivity<60000){var tick=await supabase.rpc('tick_player_visit',{session_id:visitId});if(tick.error)console.warn('Aktif kullanım süresi güncellenemedi:',tick.error.message);}},30000);}
async function loadAdmin(){var r=await supabase.from('players').select('*,player_season_stats(*)').is('archived_at',null).order('full_name');if(r.error)throw r.error;await applyAutoSuccess(r.data);var owner=await supabase.rpc('is_club_owner');if(owner.error)throw owner.error;canManageRoles=Boolean(owner.data);var roles=await supabase.rpc('player_account_roles');if(roles.error)throw roles.error;accountRoles={};(roles.data||[]).forEach(p=>accountRoles[p.player_id]=p.role);el('roster').innerHTML=(r.data||[]).sort(positionOrder).map(function(p){var s=(p.player_season_stats||[]).find(x=>x.season===selectedSeason)||{};return '<article class="player-row"><form class="player-edit" data-id="'+p.id+'" data-disabled="'+Boolean(p.access_disabled)+'"><h3>'+safe(p.full_name)+'</h3><label>Yönetim görevi<input name="management_role" value="'+safe(p.management_role)+'"></label><label>Oyuncunun grubu<input name="group_name" value="'+safe(p.group_name)+'"></label><label>Ad soyad<input name="full_name" required value="'+safe(p.full_name)+'"></label><label>Forma no<input name="jersey_number" type="number" min="0" value="'+safe(p.jersey_number)+'"></label><label>Mevki<input name="position" placeholder="Mevki gir" value="'+safe(p.position)+'"></label><label>Oyuncu durumu<input name="status" value="'+safe(p.status||'Aktif')+'"></label><label>Performans durumu<select name="performance_label">'+performanceLabels.map(label=>'<option value="'+safe(label)+'" '+(label===(p.performance_label||'Değerlendirilmedi')?'selected':'')+'>'+safe(label)+'</option>').join('')+'</select></label><label>Gelişim hedefi / yönetici notu<textarea name="development_goal" rows="4" maxlength="2000" placeholder="Bu oyuncunun çalışması gereken hedefleri yaz">'+safe(p.development_goal||'')+'</textarea></label><div class="goal-presets"></div><h4>Maç ve antrenman istatistikleri</h4><div class="stats-form">'+Object.entries(statLabels).map(([k,l])=>'<label>'+l+'<input name="'+k+'" type="number" min="0" '+(k==='success_rate'?'max="100" step="0.1"':'step="1"')+' value="'+numberValue(s[k])+'"></label>').join('')+'</div><label>Yeni rapor / yönetici mesajı<textarea name="player_note" rows="4" maxlength="10000" placeholder="Oyuncuya raporunu veya mesajını yaz">'+safe('')+'</textarea></label><button type="submit">Değişiklikleri kaydet</button><p class="save-message" aria-live="polite"></p><button type="button" class="history-button">Rapor geçmişi / çöp kutusu</button><div class="report-history"></div></form></article>';}).join('');el('roster').querySelectorAll('.player-edit').forEach(f=>f.addEventListener('submit',savePlayer));el('roster').querySelectorAll('.history-button').forEach(b=>b.onclick=()=>{var f=b.closest('form');reportHistory(f.querySelector('.report-history'),f.dataset.id,true);});el('add-player-form').onsubmit=addPlayer;await teamSummary(r.data||[]);compactCards();setupDevelopmentGoals();setupFilters(r.data||[]);await accountTools();await adminInbox();setupDashboardSections();show('admin-view');}
async function savePlayer(e){e.preventDefault();var f=e.target,msg=f.querySelector('.save-message'),button=f.querySelector('button[type=submit]'),d=new FormData(f);button.disabled=true;msg.textContent='Kaydediliyor...';try{var p={full_name:d.get('full_name').trim(),jersey_number:d.get('jersey_number')===''?null:Number(d.get('jersey_number')),position:d.get('position').trim()||null,status:d.get('status').trim()||'Aktif',group_name:d.get('group_name').trim()||null,management_role:d.get('management_role').trim()||null,performance_label:d.get('performance_label')||'Değerlendirilmedi',development_goal:String(d.get('development_goal')||'').trim()},s={};Object.keys(statLabels).forEach(k=>s[k]=numberValue(d.get(k)));var r=await supabase.rpc('club_save_player',{p_id:f.dataset.id,p_season:selectedSeason,p_player:p,p_stats:s});if(r.error)throw r.error;await saveNewReport(f.dataset.id,d.get('player_note')||'');f.querySelector('[name=player_note]').value='';var all=await supabase.from('players').select('*,player_season_stats(*)').is('archived_at',null);if(!all.error){await teamSummary(all.data||[]);setupFilters(all.data||[]);}msg.textContent='Bilgiler kaydedildi. Yeni rapor geçmişe eklendi.';applyFilters();return true;}catch(x){msg.textContent='Kaydedilemedi: '+x.message;return false;}finally{button.disabled=false;}}
async function addPlayer(e){e.preventDefault();var f=e.target,d=new FormData(f),b=f.querySelector('button');b.disabled=true;el('admin-message').textContent='Oyuncu ekleniyor...';try{var r=await supabase.from('players').insert({full_name:d.get('full_name').trim(),jersey_number:d.get('jersey_number')===''?null:Number(d.get('jersey_number')),position:d.get('position').trim()||null,status:'Aktif',birth_date:d.get('birth_date')||null,joined_at:d.get('joined_at')||null,join_year:d.get('joined_at')?Number(String(d.get('joined_at')).slice(0,4)):d.get('join_year')?Number(d.get('join_year')):null});if(r.error)throw r.error;f.reset();await loadAdmin();el('admin-message').textContent='Oyuncu eklendi. İstatistiklerini aşağıdan girebilirsin.';}catch(x){el('admin-message').textContent='Oyuncu eklenemedi: '+x.message;}finally{b.disabled=false;}}
async function refresh(){var userResult=await supabase.auth.getUser();var user=userResult.data.user;if(!user){show("login-view");return;}var profileResult=await supabase.from("profiles").select("role,player_id").eq("id",user.id).single();if(profileResult.error){throw new Error("Bu hesap için yetki kaydı bulunamadı.");}if(profileResult.data.role!=="admin"){var access=await supabase.rpc("player_access_allowed");if(access.error)throw access.error;if(!access.data){await supabase.auth.signOut();show("login-view");throw new Error("Oyuncu erişiminiz yönetici tarafından kapatılmış.");}}activeRole=profileResult.data.role;await setupSeasons(profileResult.data.role==="admin");if(profileResult.data.role==="admin"){await loadAdmin();}else{el("roster").innerHTML="";if(el("roster-list"))el("roster-list").innerHTML="";await loadPlayer(profileResult.data.player_id);}}
async function start(){try{if(!config||!config.supabaseUrl||!config.supabaseAnonKey){throw new Error("Bağlantı ayarları eksik.");}supabase=createClient(config.supabaseUrl,config.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});window.MKSK_DB=supabase;inviteLoginUi();initLoginHelp();el("login-form").addEventListener("submit",async function(event){event.preventDefault();if(el("login-form").dataset.loginMode==="signup"){el("invite-signup-action").click();return;}await loginRequest(async function(){var response=await supabase.auth.signInWithPassword({email:el('email').value.trim(),password:el('password').value});if(response.error){var code=response.error.code||'';if(code==='invalid_credentials')throw new Error('E-posta veya uygulama şifresi uyuşmuyor. Bilgilerini kontrol et. İlk girişinse önce HESAP OLUŞTUR’u seç.');if(code==='email_not_confirmed')throw new Error('Hesap giriş ayarı henüz yenilenmemiş olabilir. Sayfayı yenile; sürerse yöneticine haber ver.');throw response.error;}loginStatus('GİRİŞ DOĞRULANDI, PANELİN AÇILIYOR...');await claimInvite();await refresh();},'GİRİŞ KONTROL EDİLİYOR... LÜTFEN BEKLE.');});el("logout").addEventListener("click",async function(){if(visitTimer)clearInterval(visitTimer);visitTimer=null;visitId=null;await supabase.auth.signOut();show("login-view");});await supabase.auth.getSession();if(helpRecoveryActive){showRecoveryView();return;}if(new URLSearchParams(location.search).has("giris-yardim")){show("login-view");openLoginHelp();return;}await refresh();}catch(error){el("login-error").textContent="Uygulama başlatılamadı: "+error.message;show("login-view");}}

async function saveNewReport(playerId,body){if(!body.trim())return;var u=(await supabase.auth.getUser()).data.user;var p=await supabase.from('profiles').select('player_id').eq('id',u.id).single();var name='Yönetici';if(p.data?.player_id){var who=await supabase.from('players').select('full_name').eq('id',p.data.player_id).single();name=who.data?.full_name||name;}var r=await supabase.from('player_report_history').insert({player_id:playerId,body:body.trim(),author_id:u.id,author_name:name});if(r.error)throw r.error;}
async function reportHistory(box,playerId,isAdmin){box.textContent='Raporlar yükleniyor...';var r=await supabase.from('player_report_history').select('*').eq('player_id',playerId).order('created_at',{ascending:false});if(r.error){box.textContent='Raporlar açılamadı: '+r.error.message;return;}var rows=r.data||[];box.innerHTML='<h4>Rapor geçmişi</h4><div class="active-reports"></div>'+(isAdmin?'<details><summary>Çöp kutusu</summary><div class="trash-reports"></div></details>':'');for(var h of rows){var target=box.querySelector(h.deleted_at?'.trash-reports':'.active-reports');if(!target)continue;var item=document.createElement('article');item.style.cssText='background:#e6f3ff;border-left:4px solid #edce37;padding:12px;margin:10px 0;border-radius:8px';var meta=document.createElement('small');meta.textContent=new Date(h.created_at).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'})+' · '+h.author_name;item.appendChild(meta);var body=document.createElement('p');body.textContent=h.body;body.style.whiteSpace='pre-wrap';item.appendChild(body);if(isAdmin){if(!h.deleted_at){var edit=document.createElement('button');edit.type='button';edit.textContent='Düzenle';edit.onclick=function(record,node){return function(){var t=document.createElement('textarea');t.value=record.body;t.rows=4;var save=document.createElement('button');save.type='button';save.textContent='Rapor değişikliğini kaydet';save.onclick=async function(){if(!t.value.trim())return;save.disabled=true;var q=await supabase.from('player_report_history').update({body:t.value.trim(),updated_at:new Date().toISOString()}).eq('id',record.id);if(q.error){save.disabled=false;alert(q.error.message);}else await reportHistory(box,playerId,true);};node.append(t,save);this.disabled=true;};}(h,item);item.appendChild(edit);}var action=document.createElement('button');action.type='button';action.textContent=h.deleted_at?'Geri al':'Çöp kutusuna taşı';action.onclick=function(record){return async function(){this.disabled=true;var q=await supabase.from('player_report_history').update({deleted_at:record.deleted_at?null:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',record.id);if(q.error){this.disabled=false;alert(q.error.message);}else await reportHistory(box,playerId,true);};}(h);item.appendChild(action);}target.appendChild(item);}if(!rows.some(h=>!h.deleted_at))box.querySelector('.active-reports').textContent='Henüz rapor bulunmuyor.';}

