async function changePlayerAccess(id,b){var f=Array.from(document.querySelectorAll('.player-edit')).find(f=>f.dataset.id===id),disabled=f.dataset.disabled!=='true',name=f.querySelector('[name=full_name]').value;if(!confirm(name+' için '+(disabled?'uygulama erişimi kapatılacak. İstatistikler ve raporlar silinmez.'+(accountRoles[id]==='admin'?' Yönetici yetkisi de kaldırılacak.':''):'uygulama erişimi yeniden açılacak.')+' Onaylıyor musun?'))return;b.disabled=true;var r=await supabase.rpc('set_player_access',{target_player:id,disabled});if(r.error){el('admin-message').textContent='Erişim değiştirilemedi: '+r.error.message;b.disabled=false;return;}f.dataset.disabled=String(disabled);if(disabled&&accountRoles[id]==='admin')accountRoles[id]='player';el('admin-message').textContent=name+' — Erişim '+(disabled?'kapatıldı. Eski kullanılmamış davetler iptal edildi.':'açıldı. Oyuncu kendi hesabıyla tekrar girebilir.');applyFilters();}

async function playerMessageBox(playerId){var box=el('player-message-box');if(!box){box=document.createElement('section');box.id='player-message-box';box.className='card';el('player-view').appendChild(box);}box.innerHTML='<h3>Yönetime mesaj gönder</h3><p>Mesajını yalnızca yöneticiler ve sen görebilirsin.</p><form><label>Mesajın<textarea name="message" maxlength="2000" rows="4" required placeholder="Takım yönetimine iletmek istediğin mesajı yaz"></textarea></label><button type="submit">Mesajı gönder</button><p class="message-status" aria-live="polite"></p></form><details><summary>Gönderdiğim mesajlar</summary><div class="sent-messages"></div></details>';async function history(){var r=await supabase.from('player_messages').select('body,created_at,read_at').eq('player_id',playerId).order('created_at',{ascending:false}).limit(100),area=box.querySelector('.sent-messages');if(r.error){area.textContent='Mesajlar yüklenemedi: '+r.error.message;return;}area.innerHTML=(r.data||[]).map(m=>'<article class="message-item"><small>'+safe(new Date(m.created_at).toLocaleString('tr-TR'))+' · '+(m.read_at?'Okundu':'Gönderildi')+'</small><p>'+safe(m.body)+'</p></article>').join('')||'<p>Henüz mesaj göndermedin.</p>';}box.querySelector('details').ontoggle=()=>{if(box.querySelector('details').open)history();};box.querySelector('form').onsubmit=async e=>{e.preventDefault();if(window.MKSK_PLAYER_PREVIEW)return;var f=e.target,b=f.querySelector('button'),status=f.querySelector('.message-status'),body=new FormData(f).get('message').trim();if(!body)return;b.disabled=true;status.textContent='Gönderiliyor...';var r=await supabase.from('player_messages').insert({player_id:playerId,body});if(r.error){status.textContent='Gönderilemedi: '+r.error.message;}else{f.reset();status.textContent='Mesajın yönetime gönderildi.';await history();}b.disabled=false;};}
async function adminInbox(){var box=el('admin-inbox');if(!box){box=document.createElement('section');box.id='admin-inbox';box.className='card';el('add-player-form').after(box);}box.innerHTML='<details><summary>Oyuncu mesajları <span class="unread-count"></span></summary><p>Oyunculardan gelen özel mesajlar. Okuduğun mesajı işaretleyebilirsin.</p><button type="button" class="refresh-inbox">Mesajları yenile</button><label>Mesaj filtresi<select class="inbox-filter"><option value="all">Tüm mesajlar</option><option value="unread">Okunmamış mesajlar</option><option value="read">Okunmuş mesajlar</option></select></label><div class="inbox-results"></div><button type="button" class="more-messages">Daha fazla mesaj yükle</button></details>';var page=0,rows=[],unread=await supabase.from('player_messages').select('id',{count:'exact',head:true}).is('read_at',null);box.querySelector('.unread-count').textContent=unread.error?'(sayı yüklenemedi)':'('+unread.count+' okunmamış)';async function load(reset){if(reset){page=0;rows=[];}var area=box.querySelector('.inbox-results'),q=supabase.from('player_messages').select('id,body,created_at,read_at,players(full_name)').order('created_at',{ascending:false}).range(page*50,page*50+49),filter=box.querySelector('select').value;if(filter==='unread')q=q.is('read_at',null);if(filter==='read')q=q.not('read_at','is',null);var r=await q;if(r.error){area.textContent='Mesajlar yüklenemedi: '+r.error.message;return;}rows=rows.concat(r.data||[]);page++;area.innerHTML=rows.map(m=>'<article class="message-item '+(!m.read_at?'unread':'')+'" data-message="'+m.id+'"><strong>'+safe(m.players?.full_name||'Oyuncu')+'</strong><small>'+safe(new Date(m.created_at).toLocaleString('tr-TR'))+' · '+(m.read_at?'Okundu':'Yeni mesaj')+'</small><p>'+safe(m.body)+'</p>'+(!m.read_at?'<button type="button" class="mark-read">Okundu işaretle</button>':'')+'</article>').join('')||'<p>Bu bölümde henüz mesaj yok.</p>';box.querySelector('.more-messages').hidden=(r.data||[]).length<50;area.querySelectorAll('.mark-read').forEach(b=>b.onclick=async()=>{b.disabled=true;var r=await supabase.from('player_messages').update({read_at:new Date().toISOString()}).eq('id',b.closest('article').dataset.message);if(r.error){b.disabled=false;alert(r.error.message);return;}await load(true);var c=await supabase.from('player_messages').select('id',{count:'exact',head:true}).is('read_at',null);if(!c.error)box.querySelector('.unread-count').textContent='('+c.count+' okunmamış)';});}box.querySelector('details').ontoggle=()=>{if(box.querySelector('details').open)load(true);};box.querySelector('.refresh-inbox').onclick=()=>load(true);box.querySelector('select').onchange=()=>load(true);box.querySelector('.more-messages').onclick=()=>load(false);}

async function changeManagerRole(id,b){var f=Array.from(document.querySelectorAll('.player-edit')).find(f=>f.dataset.id===id),enabled=accountRoles[id]!=='admin',name=f.querySelector('[name=full_name]').value;if(!confirm(name+' için '+(enabled?'yönetici yetkisi açılacak. Tüm oyuncuları ve raporları görebilecek, kadro ve istatistikleri düzenleyebilecek.':'yönetici yetkisi kaldırılacak. Yalnızca kendi oyuncu bilgilerini görebilecek.')+' Onaylıyor musun?'))return;b.disabled=true;var r=await supabase.rpc('set_player_manager',{target_player:id,enabled});if(r.error){el('admin-message').textContent='Yetki değiştirilemedi: '+r.error.message;b.disabled=false;return;}accountRoles[id]=enabled?'admin':'player';el('admin-message').textContent=name+' — Yönetici yetkisi '+(enabled?'açıldı.':'kaldırıldı.');applyFilters();}

setInterval(async()=>{if(!supabase||!activeRole)return;var u=(await supabase.auth.getUser()).data.user;if(!u)return;var p=await supabase.from('profiles').select('role').eq('id',u.id).single();if(!p.error&&p.data.role!==activeRole){try{await refresh();}catch(e){show('login-view');el('login-error').textContent=e.message;}}},30000);

function penaltyState(p){return p.cancelled?'İptal edildi':p.served_matches.length>=p.total_matches?'Tamamlandı':'Devam ediyor';}
function penaltyDate(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date());}
function penaltyFields(p){return '<label>Ceza nedeni<textarea name="reason" maxlength="2000" required>'+safe(p.reason||'')+'</textarea></label><label>Yönetici açıklaması<textarea name="note" maxlength="4000">'+safe(p.note||'')+'</textarea></label><div class="stats-form"><label>Verildiği tarih<input name="given_on" type="date" required value="'+safe(p.given_on||penaltyDate())+'"></label><label>Toplam ceza maçı<input name="total_matches" type="number" min="1" max="100" step="1" required value="'+(p.total_matches||1)+'"></label></div><label>Cezanın çekildiği maçlar (her satıra bir maç)<textarea name="served" rows="4" maxlength="20000" placeholder="14.10.2026 — Rakip takım">'+safe((p.served_matches||[]).join('\n'))+'</textarea></label><p>Yalnızca gerçekten ceza çekilen maçları yaz. Takımın maç sayısı cezayı otomatik azaltmaz.</p>';}
async function penaltiesPanel(isAdmin,playerId){var id=isAdmin?'admin-penalties':'player-penalties',box=el(id);if(!box){box=document.createElement('section');box.id=id;box.className='card';box.hidden=true;el(isAdmin?'admin-view':'player-view').appendChild(box);}box.innerHTML='<h3>'+ (isAdmin?'Ceza yönetimi':'Cezalarım')+'</h3><div class="penalty-alert" role="status"></div>'+(isAdmin?'<details><summary>Yeni ceza ekle</summary><form class="new-penalty"><label>Oyuncu<select name="player_id" required>'+Array.from(document.querySelectorAll('.player-edit')).map(f=>'<option value="'+safe(f.dataset.id)+'">'+safe(f.querySelector('[name=full_name]').value)+'</option>').join('')+'</select></label>'+penaltyFields({})+'<button type="submit">Cezayı kaydet</button><p class="penalty-message" aria-live="polite"></p></form></details>':'')+'<label>Ceza filtresi<select class="penalty-filter"><option value="">Tümü</option><option>Devam ediyor</option><option>Tamamlandı</option><option>İptal edildi</option></select></label><button type="button" class="refresh-penalties">Cezaları yenile</button><div class="penalty-results"></div>';var rows=[];
async function load(){var q=supabase.from('player_penalties').select('*,players(full_name)').eq('season',selectedSeason).order('given_on',{ascending:false}).order('created_at',{ascending:false});if(!isAdmin)q=q.eq('player_id',playerId).eq('cancelled',false);var all=[];for(var offset=0;;offset+=500){var r=await q.range(offset,offset+499);if(r.error){box.querySelector('.penalty-results').textContent='Cezalar yüklenemedi: '+r.error.message;return;}all.push(...r.data);if(r.data.length<500)break;}rows=all;draw();}
function draw(){var filter=box.querySelector('.penalty-filter').value,completed=rows.filter(p=>penaltyState(p)==='Tamamlandı').length;box.querySelector('.penalty-alert').textContent=isAdmin&&completed?completed+' cezanın maçları tamamlandı. Oyuncuların cezaları bitti.':'';box.querySelector('.penalty-results').innerHTML=rows.filter(p=>!filter||penaltyState(p)===filter).map(p=>{var state=penaltyState(p),remaining=p.cancelled?0:Math.max(0,p.total_matches-p.served_matches.length);return '<article class="penalty-item" data-penalty="'+p.id+'" style="background:'+(p.cancelled?'#edf0f5':remaining?'#fff0e5':'#e5f7ee')+';border-left:5px solid '+(remaining?'#e67835':'#218c65')+';padding:18px;border-radius:14px;margin:14px 0"><h4>'+safe(p.players?.full_name||'Oyuncu')+'</h4><strong>'+safe(state)+'</strong><p>'+safe(p.given_on)+' · '+safe(p.reason)+'</p><p style="white-space:pre-wrap">'+safe(p.note)+'</p><div class="summary-grid">'+playerHtml('Toplam ceza',p.total_matches+' maç')+playerHtml('Tamamlanan',p.served_matches.length+' maç')+playerHtml('Kalan',remaining+' maç')+'</div><details><summary>Cezanın çekildiği maçlar</summary><ul>'+p.served_matches.map(m=>'<li>'+safe(m)+'</li>').join('')+'</ul></details>'+(isAdmin?'<button type="button" class="edit-penalty">Cezayı düzenle / maç işle</button><button type="button" class="cancel-penalty">'+(p.cancelled?'Geri al':'Cezayı sil')+'</button>':'')+'</article>';}).join('')||'<p>Bu sezon ve filtre için ceza bulunmuyor.</p>';box.querySelectorAll('.edit-penalty').forEach(b=>b.onclick=()=>edit(rows.find(p=>p.id===b.closest('article').dataset.penalty)));box.querySelectorAll('.cancel-penalty').forEach(b=>b.onclick=async()=>{var p=rows.find(p=>p.id===b.closest('article').dataset.penalty);if(!confirm(p.cancelled?'Ceza yeniden aktif edilsin mi?':'Ceza iptal edilsin mi? Kayıt geçmişte saklanır.'))return;b.disabled=true;var r=await supabase.from('player_penalties').update({cancelled:!p.cancelled}).eq('id',p.id);if(r.error){alert(r.error.message);b.disabled=false;}else await load();});}
async function save(f,p){var d=new FormData(f),total=Number(d.get('total_matches')),matches=String(d.get('served')||'').split('\n').map(x=>x.trim()).filter(Boolean),msg=f.querySelector('.penalty-message'),b=f.querySelector('button[type=submit]');if(new Set(matches.map(x=>x.toLocaleLowerCase('tr-TR'))).size!==matches.length||matches.length>total||matches.some(x=>x.length>250)){msg.textContent='Maçlar tekrarlanmamalı, toplam cezayı aşmamalı ve her satır en fazla 250 karakter olmalı.';return;}var payload={reason:String(d.get('reason')).trim(),note:String(d.get('note')).trim(),given_on:d.get('given_on'),total_matches:total,served_matches:matches};if(!payload.reason){msg.textContent='Ceza nedenini yaz.';return;}b.disabled=true;msg.textContent='Kaydediliyor...';try{var q=p?supabase.from('player_penalties').update(payload).eq('id',p.id):supabase.from('player_penalties').insert({...payload,player_id:d.get('player_id'),season:selectedSeason});var r=await q;if(r.error)throw r.error;msg.textContent='Ceza kaydedildi.';await load();return true;}catch(e){msg.textContent='Kaydedilemedi: '+e.message;return false;}finally{b.disabled=false;}}
function edit(p){var dialog=document.createElement('dialog');dialog.style.cssText='width:min(92vw,700px);max-height:90vh;overflow:auto;border:0;border-radius:18px';dialog.innerHTML='<h3>Ceza düzenle</h3><form>'+penaltyFields(p)+'<button type="submit">Değişiklikleri kaydet</button><p class="penalty-message" aria-live="polite"></p></form><button type="button" class="close-penalty">Kapat</button>';dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(await save(e.target,p))dialog.close();};dialog.querySelector('.close-penalty').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();document.body.appendChild(dialog);dialog.showModal();}
if(isAdmin)box.querySelector('.new-penalty').onsubmit=async e=>{e.preventDefault();if(await save(e.target,null))e.target.reset();};box.querySelector('.refresh-penalties').onclick=load;box.querySelector('.penalty-filter').onchange=draw;await load();}
var beforePenaltyAdmin=loadAdmin;loadAdmin=async function(){await beforePenaltyAdmin();await penaltiesPanel(true);var nav=el('dashboard-nav');if(!nav.querySelector('[data-page=penalties]')){var b=document.createElement('button');b.type='button';b.dataset.page='penalties';b.textContent='Ceza yönetimi';b.onclick=()=>setDashboardPage('penalties');nav.appendChild(b);}setDashboardPage(dashboardPage);};
