function penaltyTheme(){var style=document.createElement('style');style.textContent='#admin-penalties,#player-penalties,.penalty-stats-summary{background:linear-gradient(135deg,#fff0df,#fff7f2);border:1px solid #f4be99;border-top:5px solid #d55c24}#dashboard-nav [data-page="penalties"],#player-nav [data-player-page="penalties"]{background:linear-gradient(135deg,#e17532,#b83b29);color:#fff;border-color:#d45d28}#admin-penalties button,#player-penalties button,.close-penalty{background:#bc4922;color:#fff;border:0;border-radius:10px;padding:12px 18px;font-weight:700}#admin-penalties button:hover{background:#943819}.new-penalty textarea,.new-penalty select,.new-penalty input{width:100%;padding:12px;border:1px solid #edb18e;border-radius:10px;background:#fffaf6;box-sizing:border-box;font:inherit}.new-penalty label{display:block;margin:14px 0}.new-penalty summary{color:#ad3e20}.penalty-stats-summary{padding:18px;border-radius:14px;margin:20px 0}.penalty-stats-summary article{border-bottom:1px solid #eac1a8;padding:12px 0}.penalty-stats-summary p{white-space:pre-wrap}';document.head.appendChild(style);}
async function penaltyStatsSummary(box,playerId){box.className='penalty-stats-summary';box.textContent='Ceza bilgisi yükleniyor...';var q=await supabase.from('player_penalties').select('*').eq('player_id',playerId).eq('season',selectedSeason).order('given_on',{ascending:false});q.data=(q.data||[]).filter(p=>!p.cancelled);if(!box.isConnected)return;if(q.error){box.textContent='Ceza bilgisi yüklenemedi: '+q.error.message;return;}box.innerHTML='<h3>Ceza durumu</h3>'+(q.data.length?q.data.map(p=>'<article><strong>'+safe(penaltyState(p))+'</strong><p>'+safe(p.given_on)+' · '+safe(p.reason)+'</p><p>'+safe(p.note)+'</p><div class="summary-grid">'+playerHtml('Toplam ceza',p.total_matches+' maç')+playerHtml('Tamamlanan',p.served_matches.length+' maç')+playerHtml('Kalan', (p.cancelled?0:Math.max(0,p.total_matches-p.served_matches.length))+' maç')+'</div></article>').join(''):'<p>Bu sezon için ceza kaydı yok.</p>');}
