var clubMetadataRows=[];
function clubToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date());}
function clubDate(s){if(!s)return 'Belirtilmedi';return s.split('-').reverse().join('.');}
function clubUtc(s){return new Date(s+'T00:00:00Z');}
function clubSpan(start,end){if(!start)return 'Giriş tarihi eksik';if(start>end)return 'Henüz katılmadı';var a=clubUtc(start),b=clubUtc(end),months=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth();function anchor(n){var y=a.getUTCFullYear(),m=a.getUTCMonth()+n,last=new Date(Date.UTC(y,m+1,0)).getUTCDate();return new Date(Date.UTC(y,m,Math.min(a.getUTCDate(),last)));}if(anchor(months)>b)months--;var days=Math.round((b-anchor(months))/86400000);return Math.floor(months/12)+' yıl '+months%12+' ay '+days+' gün';}
function clubTenure(p){if(p.access_disabled&&!p.team_left_on)return 'Ayrılış tarihi gerekli';if(p.joined_at)return clubSpan(p.joined_at,p.team_left_on||clubToday());if(p.join_year)return 'Giriş yılı: '+p.join_year+' — tam süre için tarih gerekli';return 'Giriş tarihi eksik';}
function clubActive(p){return !p.access_disabled&&!p.team_left_on;}
function clubNextBirthday(p,today){if(!p.birth_date)return null;var b=clubUtc(p.birth_date),t=clubUtc(today);function next(y){var month=b.getUTCMonth(),day=b.getUTCDate();if(month===1&&day===29&&new Date(Date.UTC(y,2,0)).getUTCDate()===28)day=28;return new Date(Date.UTC(y,month,day));}var n=next(t.getUTCFullYear());if(n<t)n=next(t.getUTCFullYear()+1);return {player:p,days:Math.round((n-t)/86400000),date:n.toISOString().slice(0,10)};}
function clubMetadataStyle(){var s=document.createElement('style');s.textContent='#jersey-panel{background:linear-gradient(135deg,#e6f7f1,#effbff);border-top:5px solid #138769}#player-info-panel{background:linear-gradient(135deg,#eeeaff,#f8f5ff);border-top:5px solid #7855b7}.free-jersey-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:10px;margin:18px 0}.free-jersey-grid button{background:#148969;color:#fff;border:0;border-radius:12px;padding:14px 6px;font-size:20px;font-weight:bold}.birthday-notice{border-left:5px solid #bb8a17;background:#fff3ce;padding:14px;border-radius:12px;margin:18px 0}.club-info-item{background:white;border-left:4px solid #8057b9;border-radius:14px;padding:18px;margin:12px 0}.club-info-fields input,.club-info-fields select,#jersey-panel input,#jersey-panel select{width:100%;padding:12px;border:1px solid #c9bce3;border-radius:10px;box-sizing:border-box;font:inherit}.club-info-fields label{display:block;margin:12px 0}#player-info-panel button{background:#7750ac;color:white;border:0;border-radius:10px;padding:12px 16px}#jersey-panel button{border-radius:12px}.club-info-controls{display:flex;gap:12px;flex-wrap:wrap;margin:15px 0}.club-info-controls label{flex:1;min-width:150px}.club-own-info{background:#eee9ff;border-left:5px solid #8057b9;border-radius:14px;padding:18px;margin:18px 0}#dashboard-nav [data-page="jerseys"]{background:#148969;color:white}#dashboard-nav [data-page="player_info"]{background:#7750ac;color:white}';document.head.appendChild(s);}
function clubDateFields(p){return '<div class="club-info-fields"><label>Doğum tarihi<input name="birth_date" type="date" max="'+clubToday()+'" value="'+safe(p.birth_date||'')+'"></label><label>Takıma giriş tarihi<input name="joined_at" type="date" value="'+safe(p.joined_at||'')+'"></label><label>Yalnızca giriş yılı biliniyorsa<input name="join_year" type="number" min="1900" max="2100" value="'+safe(p.join_year||'')+'"></label><label>Takımdan ayrılış tarihi (ayrıldıysa)<input name="team_left_on" type="date" value="'+safe(p.team_left_on||'')+'"></label></div>';}
