// Personal progress and published own lineup assignment, with no player-side writes.
var selfGrowthPlayer=null,selfGrowthToken=0;
function selfMetric(label,value){return playerHtml(safe(label),safe(value));}
function selfNumber(value){return value===null||value===undefined||!Number.isFinite(Number(value))?null:Number(value);}
function selfFmt(value){return value==null?'—':Number(value).toLocaleString('tr-TR',{maximumFractionDigits:1});}
function selfProgressChart(games){if(!games.length)return '<p class="self-empty">GRAFİK İÇİN MAÇ BAZINDA PUAN KAYDI BEKLENİYOR. ESKİ TOPLAMLARINDAN MAÇ PUANI TAHMİN EDİLMEZ.</p>';var width=640,left=42,right=610,top=18,bottom=190,paths=[],path='',dots='';games.forEach((g,i)=>{var v=selfNumber(g.points),x=games.length===1?(left+right)/2:left+i*(right-left)/(games.length-1);if(v==null){if(path)paths.push(path);path='';return;}var y=bottom-Math.max(0,Math.min(10,v))/10*(bottom-top);path+=(path?' L':'M')+x.toFixed(1)+' '+y.toFixed(1);dots+='<circle cx="'+x+'" cy="'+y+'" r="5" fill="#8a6bdf"><title>'+safe(clubDate(g.match_date))+' · '+v+' / 10</title></circle>';});if(path)paths.push(path);return '<div class="self-chart"><svg viewBox="0 0 640 225" role="img" aria-label="Son kayıtlı maçların 0–10 arası puan grafiği">'+[0,5,10].map(v=>{var y=bottom-v/10*(bottom-top);return '<line x1="42" x2="610" y1="'+y+'" y2="'+y+'" stroke="#7a8eb8" stroke-opacity=".45"/><text x="12" y="'+(y+5)+'" fill="currentColor" font-size="13">'+v+'</text>';}).join('')+paths.map(d=>'<path d="'+d+'" fill="none" stroke="#527bc8" stroke-width="4"/>').join('')+dots+'<text x="42" y="216" fill="currentColor" font-size="12">DAHA ESKİ KAYIT</text><text x="490" y="216" fill="currentColor" font-size="12">EN SON KAYIT</text></svg></div><p class="self-caption">ÇİZGİ YALNIZ PUAN GİRİLEN KAYITLARI BİRLEŞTİRİR; ARADAKİ PUANSIZ MAÇLAR BOŞLUKTUR, SIFIR DEĞİLDİR.</p>';}
function selfProgressHtml(data){var s=data.season_stats||{},games=data.games||[],rated=data.rated_games||[],n=Math.min(5,Math.floor(rated.length/2)),keeper=String(data.position||'').toLocaleUpperCase('tr-TR')==='GK',compare='';if(n>=2){var pair=rated.slice(-n*2),old=pair.slice(0,n),recent=pair.slice(n),mean=(rows,k)=>rows.every(g=>selfNumber(g[k])!==null)?rows.reduce((a,g)=>a+Number(g[k]),0)/rows.length:null,a=mean(old,'points'),b=mean(recent,'points'),delta=b-a,tone=delta>.05?'purple':delta<-.05?'orange':'blue',trend=delta>.05?'YÜKSELİŞ':delta<-.05?'DÜŞÜŞ':'DENGELİ';function cmp(label,key){var x=mean(old,key),y=mean(recent,key);return '<article class="self-compare"><h4>'+safe(label)+'</h4><div><span>ÖNCEKİ '+n+' PUANLI MAÇ</span><strong>'+selfFmt(x)+'</strong><span>SON '+n+' PUANLI MAÇ</span><strong>'+selfFmt(y)+'</strong></div><small>'+(x==null||y==null?'EKSİK DEĞER OLDUĞU İÇİN FARK HESAPLANMADI.':'FARK: '+(y-x>0?'+':'')+selfFmt(y-x))+'</small></article>';}
compare='<div class="self-trend '+tone+'"><strong>'+trend+'</strong><span>MAÇ PUANI ORTALAMANDA '+(delta>0?'+':'')+selfFmt(delta)+' PUAN FARK</span></div><p>ÖNCEKİ '+n+' VE SON '+n+' PUANLI MAÇ KARŞILAŞTIRILIYOR. BU YALNIZ SENİN GEÇMİŞİNLE KIYASTIR; BAŞKA OYUNCULARLA SIRALAMA DEĞİLDİR.</p><div class="self-compare-grid">'+cmp('MAÇ PUANI ORTALAMASI / 10','points')+cmp('MAÇ BAŞINA GOL','goals')+cmp('MAÇ BAŞINA ASİST','assists')+(keeper?cmp('MAÇ BAŞINA YENİLEN GOL','goals_conceded'):'')+'</div><p class="self-caption">GOL VE ASİST AYRI KATKI ÖLÇÜLERİDİR; FORM ETİKETİNE OTOMATİK EKLENMEZ. KALECİDE DAHA AZ YENİLEN GOLÜ YALNIZ KENDİ GEÇMİŞİNLE KIYASLA. '+(n<5?'AZ VERİ: HER DÖNEMDE YALNIZ '+n+' PUANLI MAÇ VAR.':'')+'</p>';}else compare='<p class="self-empty">KARŞILAŞTIRMA İÇİN VERİ BEKLENİYOR. EN AZ 4 MAÇIN PUANI GİRİLMELİ; SONRA ÖNCEKİ 2 VE SON 2 PUANLI MAÇ KIYASLANIR. ŞU AN '+rated.length+' AYRI PUAN KAYDI VAR.</p>';
return '<h3>KENDİ GELİŞİMİM</h3><p>'+safe(selectedSeason)+' · YALNIZ KENDİ KAYITLARIN</p>'+compare+'<h4>SON 10 KAYITLI MAÇIN PUAN GRAFİĞİ</h4>'+selfProgressChart(games)+'<div class="self-game-list">'+games.map(g=>'<article class="self-game"><h4>'+safe(clubDate(g.match_date))+'</h4><strong>PUAN: '+(g.points==null?'BEKLENİYOR':safe(selfFmt(g.points))+' / 10')+'</strong><p>GOL: '+safe(selfFmt(selfNumber(g.goals)))+' · ASİST: '+safe(selfFmt(selfNumber(g.assists)))+(keeper?' · YENİLEN GOL: '+safe(selfFmt(selfNumber(g.goals_conceded))):'')+'</p></article>').join('')+'</div><h4>MEVCUT SEZON TOPLAMLARIN</h4><div class="summary-grid">'+selfMetric('MAÇ SAYISI',s.matches??'—')+selfMetric('GOL',s.goals??'—')+selfMetric('ASİST',s.assists??'—')+(keeper?selfMetric('YENİLEN GOL',s.goals_conceded??'—'):'')+selfMetric('ANTRENMAN KATILIMI',s.attendance_matches??'—')+selfMetric('ANTRENMAN GOLÜ',s.attendance_goals??'—')+selfMetric('ANTRENMAN PUANI',s.attendance_points??'—')+'</div><p class="self-caption">ANTRENMANLARIN TARİHLİ TEK TEK KAYDI BULUNMADIĞI İÇİN KATILIM DEĞİŞİMİ HESAPLANMAZ.'+(keeper?' KURTARIŞ İSTATİSTİĞİ İÇİN AYRI KAYIT BULUNMUYOR.':'')+'</p><button type="button" class="self-refresh">GELİŞİMİMİ YENİLE</button>';}
function selfDutyHtml(data){if(!data.published)return '<h3>KADRO GÖREVİM</h3><p class="self-empty">BU SEZON İÇİN HENÜZ YAYIMLANMIŞ KADRO YOK. KAYITLI TASLAKLAR OYUNCULARA GÖSTERİLMEZ.</p><button type="button" class="self-refresh">KADRO GÖREVİMİ YENİLE</button>';var past=data.match_date&&data.match_date<clubToday();return '<h3>KADRO GÖREVİM</h3><p class="self-duty-badge">'+safe(data.status)+(past?' · GEÇMİŞ TARİHLİ MAÇ':'')+'</p><h4>'+safe(data.title)+'</h4><div class="summary-grid">'+selfMetric('MAÇ TARİHİ',clubDate(data.match_date))+selfMetric('MAÇ SAATİ',(data.match_time||'').slice(0,5)||'BELİRTİLMEDİ')+selfMetric('SAHA',data.venue||'BELİRTİLMEDİ')+selfMetric('KADRO BÜYÜKLÜĞÜ',data.size+' KİŞİ')+(data.selected?selfMetric('GÖREV MEVKİM',data.role||'BELİRTİLMEDİ'):'')+'</div>'+(data.selected?'<h4>BANA ÖZEL MAÇ GÖREVİ</h4><p class="self-task">'+safe(data.task||'YÖNETİCİN BU MAÇ İÇİN ÖZEL GÖREV NOTU YAZMADI.')+'</p>':'<p class="self-empty">SON YAYIMLANAN KADRODA YER ALMIYORSUN. BAŞKA OYUNCULARIN GÖREV NOTLARI GÖSTERİLMEZ.</p>')+'<p class="self-caption">YAYIN SÜRÜMÜ '+safe(data.revision)+' · '+safe(new Date(data.published_at).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))+'. YALNIZ YAYIMLANAN SON KADRO GÖRÜNÜR; TASLAK DEĞİŞİKLİKLERİ YANSIMAZ.</p><button type="button" class="self-refresh">KADRO GÖREVİMİ YENİLE</button>';}
