async function selfGrowthLoad(id){var token=++selfGrowthToken,seasonKey=selectedSeason;selfGrowthPlayer=id;var targets=[['player-self-growth','club_player_progress',selfProgressHtml],['player-own-duty','club_my_lineup',selfDutyHtml]];targets.forEach(([key])=>{var box=el(key);if(!box){box=document.createElement('section');box.id=key;box.className='card self-growth-panel';box.hidden=true;el('player-view').appendChild(box);}box.innerHTML='<p role="status">KAYITLARIN YÜKLENİYOR...</p>';});selfGrowthVisibility();await Promise.all(targets.map(async([key,rpc,render])=>{var box=el(key);try{var r=await supabase.rpc(rpc,{p_player:id,p_season:seasonKey});if(r.error)throw r.error;if(token!==selfGrowthToken||selectedSeason!==seasonKey)return;if(rpc==='club_my_lineup')recordPlayerDuty(id,seasonKey,r.data);box.innerHTML=render(r.data);box.querySelector('.self-refresh').onclick=()=>selfGrowthLoad(id);}catch(e){if(token!==selfGrowthToken)return;if(rpc==='club_my_lineup')recordPlayerDuty(id,seasonKey,null);box.innerHTML='<p role="alert">YÜKLENEMEDİ: '+safe(e.message)+'</p><button type="button" class="self-refresh">TEKRAR DENE</button>';box.querySelector('button').onclick=()=>selfGrowthLoad(id);}}));selfGrowthVisibility();}
