function stepInstall(){document.querySelectorAll('.player-edit').forEach(f=>{if(f.querySelector('.player-step-nav'))return;var nav=document.createElement('section');nav.className='player-step-nav';nav.innerHTML='<h4>OYUNCULAR ARASINDA İLERLE</h4><p class="step-position"></p><p class="step-target"></p><div class="step-actions"><button type="button" class="step-prev">ÖNCEKİ OYUNCU</button><button type="button" class="step-next">KAYDET VE SONRAKİ OYUNCUYA GEÇ</button></div><p class="step-message" role="status"></p>';(f.querySelector('.data-entry-body')||f).appendChild(nav);f.dataset.stepSaved=stepSnapshot(f);nav.querySelector('.step-prev').onclick=()=>{if(stepNavBusy)return;var forms=stepForms(),i=forms.indexOf(f);if(i<=0)return;if(stepSnapshot(f)!==f.dataset.stepSaved&&!confirm('BU OYUNCUDA KAYDEDİLMEMİŞ DEĞİŞİKLİKLER VAR. KAYDETMEDEN ÖNCEKİ OYUNCUYA GEÇİLSİN Mİ? TASLAK BU SAYFADA KALIR.'))return;stepOpen(forms[i-1].dataset.id);};nav.querySelector('.step-next').onclick=async()=>{if(stepNavBusy)return;if(!f.reportValidity())return;var forms=stepForms(),i=forms.indexOf(f),nextId=i>=0&&forms[i+1]?forms[i+1].dataset.id:null,msg=nav.querySelector('.step-message');stepNavBusy=true;stepUpdate();msg.textContent='KAYDEDİLİYOR...';try{var input=f.querySelector('.fair-manager-input'),ratingSave=f.querySelector('.fair-manager-save');if(input&&input.value!==input.dataset.saved){await ratingSave.onclick();if(input.value!==input.dataset.saved){msg.textContent='OYUNCU PUANI KAYDEDİLEMEDİ. AYNI OYUNCUDA KALINDI.';return;}}var saved=await savePlayer({target:f,preventDefault:function(){}});if(!saved){msg.textContent='KAYIT TAMAMLANAMADI. HATA MESAJINI KONTROL ET; GİRDİKLERİN BU EKRANDA KORUNUYOR.';return;}f.dataset.stepSaved=stepSnapshot(f);msg.textContent='KAYDEDİLDİ.';if(nextId)stepOpen(nextId);else msg.textContent='KAYDEDİLDİ. LİSTENİN SONUNDASIN.';}catch(e){msg.textContent='KAYDEDİLEMEDİ: '+e.message;}finally{stepNavBusy=false;stepUpdate();}};});stepUpdate();}
