async function drawSeasonCard(p,title,season){var rows=insightMetrics(p,false),c=document.createElement('canvas');c.width=1080;c.height=610+Math.ceil(rows.length/2)*150;var x=c.getContext('2d'),g=x.createLinearGradient(0,0,1080,c.height);g.addColorStop(0,'#173f72');g.addColorStop(1,'#533780');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.fillStyle='#f2d454';x.fillRect(0,0,1080,10);var logo=await loadClubLogo();x.drawImage(logo,880,35,145,145);function text(value,y,size,color,maxWidth=920,start=55){x.fillStyle=color;x.font='800 '+size+'px Arial';while(x.measureText(value).width>maxWidth&&size>15){size--;x.font='800 '+size+'px Arial';}x.fillText(value,start,y);}text('MECİDİYE KARAHİSAR',75,35,'#fff',790);text('SPOR KULÜBÜ',120,35,'#fff',790);text(title,205,38,'#ffe886');text(season+' · KURULUŞ: 11.06.2008',255,23,'#e4eaff');x.fillStyle='#eeeaff';x.fillRect(40,290,1000,110);text(p.full_name.toLocaleUpperCase('tr-TR'),340,38,'#23365c',940,65);text('FORMA '+(p.jersey_number??'—')+' · '+(p.position||'MEVKİ BELİRTİLMEDİ'),378,24,'#4c4775',940,65);rows.forEach(([label,value],i)=>{var bx=40+(i%2)*510,by=435+Math.floor(i/2)*150;x.fillStyle=i%2?'#e3edff':'#eee4ff';x.fillRect(bx,by,490,130);text(label,by+35,22,'#414371',450,bx+20);text(value,by+98,43,'#203b6a',450,bx+20);});text('BAŞARI = YÖNETİCİNİN GİRDİĞİ OYUNCU PUANI × 10',c.height-95,19,'#eee7ff');text('OLUŞTURULMA: '+new Date().toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul'}),c.height-60,19,'#eee7ff');text('ŞEREFİNLE OYNA, ŞEREFİNLE KAZAN',c.height-25,20,'#ffe886');return c;}
async function openSeasonCards(admin){var own=admin?null:seasonCardPlayer,b=insightBox(admin?'club-season-cards':'player-season-card',admin?'admin-view':'player-view',admin?'SEZON KARNELERİ':'SEZON KARNEM'),season=selectedSeason,token=String(Date.now())+Math.random();b.dataset.request=token;b.hidden=admin?dashboardPage!=='season_cards':playerDashboardPage!=='season_card';try{if(!admin&&!own)throw Error('OYUNCU BİLGİSİ HAZIR DEĞİL.');var rows=await insightData(own);if(b.dataset.request!==token||season!==selectedSeason)return;if(!rows.length)throw Error('AKTİF OYUNCU BULUNAMADI.');b.innerHTML='<h3>'+(admin?'SEZON KARNELERİ':'SEZON KARNEM')+'</h3><div class="insight-selectors">'+(admin?'<label>OYUNCU<select class="card-player">'+rows.map(p=>'<option value="'+p.id+'">'+safe(p.full_name)+'</option>').join('')+'</select></label>':'')+'<label>BAŞLIK<select class="card-title"><option>GÜNCEL SEZON ÖZETİ</option><option>SEZON KARNESİ</option></select></label></div><div class="season-card-preview"></div><button type="button" class="card-generate">LOGOLU GÖRSELİ HAZIRLA</button><p role="status" class="card-status"></p><div class="card-export"></div>';var selected=()=>admin?rows.find(p=>p.id===b.querySelector('.card-player').value):rows[0],title=()=>b.querySelector('.card-title').value;function draw(){if(b.dataset.imageUrl){URL.revokeObjectURL(b.dataset.imageUrl);delete b.dataset.imageUrl;}b.querySelector('.card-export').innerHTML='';b.querySelector('.card-status').textContent='';var p=selected();b.querySelector('.season-card-preview').innerHTML='<header><img alt="Kulüp logosu" src="'+safe(new URL('güncel logo.jfif',import.meta.url).href)+'"><strong>MECİDİYE KARAHİSAR SPOR KULÜBÜ</strong></header><h4>'+safe(title())+'</h4><h3>'+safe(p.full_name)+'</h3><p>'+safe(season)+' · FORMA '+safe(p.jersey_number??'—')+' · '+safe(p.position||'—')+'</p><div class="report-metrics">'+insightMetrics(p,false).map(([l,v])=>'<div><span>'+l+'</span><strong>'+v+'</strong></div>').join('')+'</div><p>BAŞARI = OYUNCU PUANI × 10. ÖZEL NOTLAR VE İLETİŞİM BİLGİLERİ PAYLAŞIMA EKLENMEZ.</p>';}b.querySelectorAll('select').forEach(s=>s.onchange=draw);b.querySelector('.card-generate').onclick=async function(){this.disabled=true;var p=selected(),heading=title(),button=this;try{b.querySelector('.card-status').textContent='GÖRSEL HAZIRLANIYOR...';var canvas=await drawSeasonCard(p,heading,season),blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('GÖRSEL HAZIRLANAMADI.');if(b.dataset.request!==token||selected().id!==p.id||title()!==heading||selectedSeason!==season)return;if(b.dataset.imageUrl)URL.revokeObjectURL(b.dataset.imageUrl);var url=URL.createObjectURL(blob);b.dataset.imageUrl=url;var fileName='MKSK-'+season+'-'+p.full_name.replace(/[^\p{L}\p{N}]+/gu,'-')+'.png';b.querySelector('.card-export').innerHTML='<img class="report-generated-image" alt="'+safe(p.full_name)+' sezon özeti"><a class="card-download">GÖRSELİ İNDİR</a><button type="button" class="card-share">GÖRSELİ PAYLAŞ</button>';b.querySelector('.report-generated-image').src=url;var link=b.querySelector('.card-download');link.href=url;link.download=fileName;b.querySelector('.card-share').onclick=async()=>{try{var file=new File([blob],fileName,{type:'image/png'});if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share)await navigator.share({files:[file],title:heading});else b.querySelector('.card-status').textContent='BU TARAYICIDA DOĞRUDAN PAYLAŞIM YOK. GÖRSELİ İNDİRİP WHATSAPP’TAN GÖNDEREBİLİRSİN.';}catch(e){if(e.name!=='AbortError')b.querySelector('.card-status').textContent='PAYLAŞILAMADI. GÖRSELİ İNDİREBİLİRSİN.';}};b.querySelector('.card-status').textContent='GÖRSEL HAZIR. İNDİREBİLİR VEYA PAYLAŞABİLİRSİN.';}catch(e){b.querySelector('.card-status').textContent=e.message;}finally{button.disabled=false;}};draw();}catch(e){b.innerHTML='<h3>SEZON KARNESİ</h3><p role="alert">AÇILAMADI: '+safe(e.message)+'</p>';}}
