(()=>{var s=document.createElement('style');s.textContent='.cm-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.cm-edit,.cm-compose{padding:20px;margin:20px 0;background:#e0d8f1;border:2px solid #8f6bbb;border-radius:18px}.cm-panel label,.cm-compose label{display:block;font-weight:700;font-size:13px;margin:10px 0}.cm-panel input:not([type=checkbox]),.cm-panel select,.cm-panel textarea,.cm-compose select,.cm-compose textarea{width:100%;box-sizing:border-box;min-width:0;margin-top:7px;padding:12px;font:inherit;border-radius:10px;border:1px solid #9e8bb8;background:#f7f2ff;color:#263d67}.cm-panel textarea,.cm-compose textarea{min-height:110px}.cm-check{display:flex!important;gap:12px;align-items:center}.cm-totals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.cm-totals div{background:#dce7f9;padding:14px;border-radius:12px}.cm-totals span{display:block;font-size:11px;line-height:1.6}.cm-totals strong{display:block;font-size:24px;margin-top:8px}.cm-status{font-weight:800}.cm-panel .cm-danger,#admin-inbox .cm-danger{background:linear-gradient(120deg,#9e4568,#7d365a)!important;color:white!important}.cm-message-alert{display:block;width:100%;box-sizing:border-box;padding:15px;margin:14px 0;border:2px solid #ce7ba8;border-radius:14px;background:linear-gradient(110deg,#93446f,#59429c);color:white;font-weight:800;cursor:pointer}.cm-message-alert[hidden]{display:none}.cm-has-unread{box-shadow:0 0 0 3px #c681b7!important}.cm-message-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:16px;line-height:1.7}.cm-mail-card{margin:16px 0}.cm-panel button,.cm-compose button{word-break:normal!important;overflow-wrap:normal!important;line-height:1.5!important;min-height:46px}.cm-panel .cm-feedback,.cm-send-status{white-space:pre-wrap;font-weight:800}html[data-theme=dark] .cm-edit,html[data-theme=dark] .cm-compose{background:#302a47;color:#f3edff}html[data-theme=dark] .cm-totals div{background:#2b4261;color:#f1eaff}html[data-theme=dark] .cm-message-text,html[data-theme=dark] .cm-compose label{color:#f1eaff!important}#dashboard-nav [data-page=team_history],#player-nav [data-player-page=team_history],#player-nav [data-player-page=manager_messages]{background:linear-gradient(120deg,#7950a7,#355c98)!important;color:white!important}@media(max-width:600px){.cm-fields{grid-template-columns:1fr}.cm-edit,.cm-compose{padding:14px}.cm-totals strong{font-size:22px}.cm-panel .awards-actions button{width:100%}}';document.head.appendChild(s);})();

function cmPlaceVisibleLinks(admin){var nav=el(admin?'dashboard-nav':'player-nav');if(!nav)return;if(admin){var after=nav.querySelector('[data-page=messages]')?.nextSibling;['team_history','season_awards'].forEach(key=>{var b=nav.querySelector('[data-page='+key+']');if(b)nav.insertBefore(b,after);});var settings=nav.querySelector('[data-page=settings]');if(settings)nav.appendChild(settings);}else{var after=nav.querySelector('[data-player-page=stats]')?.nextSibling;['my_awards','manager_messages','team_history'].forEach(key=>{var b=nav.querySelector('[data-player-page='+key+']');if(b)nav.insertBefore(b,after);});}}
