(()=>{var s=document.createElement('style');s.id='simple-login-20261019';s.textContent='.simple-login-note{padding:16px;border-radius:14px;background:#ebe4fa;color:#273c63;font-size:15px!important;line-height:1.7!important;text-transform:none!important;border-left:4px solid #8b62bb}.simple-login-privacy{font-size:12px!important;line-height:1.6!important;color:#52627b;text-transform:none!important}.login-password-toggle{min-height:44px;margin-top:10px;padding:10px 14px!important;font-size:12px!important;background:#e1e9fa!important;color:#26426b!important;border:1px solid #9daed1!important}.login-mode-tabs button{font-size:14px!important;line-height:1.5!important;white-space:normal!important;word-break:normal!important;overflow-wrap:normal!important;min-height:54px}#login-error{font-size:15px;line-height:1.7;white-space:pre-wrap;text-transform:none!important}#login-error.login-success{padding:18px;border:2px solid #6d83be;border-radius:14px;background:#dfebff;color:#173b70;font-weight:800}html[data-theme=dark] .simple-login-note{background:#28304b;color:#f0ebff;border-color:#b297df}html[data-theme=dark] .simple-login-privacy{color:#c4d2ec}html[data-theme=dark] .login-password-toggle{background:#33476b!important;color:#f4f6ff!important;border-color:#9aafd1!important}html[data-theme=dark] #login-error.login-success{background:#263e64;color:#f2f5ff;border-color:#a3bdec}';document.head.appendChild(s);})();

/* Stable, read-only navigation in player statistics and editing. */
function playerBrowseBar(id,open){var forms=stepForms(),index=forms.findIndex(f=>f.dataset.id===id),bar=document.createElement('nav');bar.className='player-browse-bar';bar.setAttribute('aria-label','Oyuncular arasında geçiş');var label=document.createElement('p');label.textContent=index<0?'Oyuncu mevcut filtrenin dışında':(index+1)+' / '+forms.length+' · '+forms[index].querySelector('[name=full_name]').value;bar.appendChild(label);[-1,1].forEach(direction=>{var target=index>=0?forms[index+direction]:null,button=document.createElement('button');button.type='button';button.textContent=direction<0?'← ÖNCEKİ OYUNCU':'SIRADAKİ OYUNCU →';button.disabled=!target;button.onclick=()=>{if(target)open(target.dataset.id);};bar.appendChild(button);});return bar;}
var navigationStats=showPlayerStatistics;showPlayerStatistics=function(id){navigationStats(id);var dialog=document.querySelector('.player-stat-dialog:last-of-type');if(!dialog)return;function open(nextId){dialog.close();showPlayerStatistics(nextId);}var top=playerBrowseBar(id,open),bottom=playerBrowseBar(id,open);dialog.prepend(top);dialog.appendChild(bottom);};
function installPlayerBrowse(){document.querySelectorAll('.player-edit').forEach(f=>{f.querySelectorAll('.player-browse-bar').forEach(n=>n.remove());function open(id){if(stepNavBusy)return;if(stepSnapshot(f)!==f.dataset.stepSaved&&!confirm('Kaydedilmemiş değişikliklerin var. Kaydetmeden diğer oyuncuya geçilsin mi? Taslağın bu sayfada kalır.'))return;stepOpen(id);}f.prepend(playerBrowseBar(f.dataset.id,open));var body=f.querySelector('.data-entry-body')||f;body.appendChild(playerBrowseBar(f.dataset.id,open));});}
var browseEditor=openPlayerEditor;openPlayerEditor=function(id){browseEditor(id);installPlayerBrowse();};var browseAdmin=loadAdmin;loadAdmin=async function(){await browseAdmin();installPlayerBrowse();};
(()=>{var style=document.createElement('style');style.id='player-navigation-and-goals-20261020';style.textContent='.player-browse-bar{padding:14px;margin:14px 0;border:1px solid #a995cc;border-radius:14px;background:#eee8fa;display:flex;flex-wrap:wrap;gap:10px}.player-browse-bar p{width:100%;margin:0;color:#273c63;font-size:14px;line-height:1.6;overflow-wrap:break-word}.player-browse-bar button{flex:1 1 160px;min-height:46px;padding:12px;font-size:13px;line-height:1.5;word-break:normal;white-space:normal;color:#fff;background:linear-gradient(120deg,#7251a7,#315c98);border:0;border-radius:10px}.player-browse-bar button:disabled{opacity:.45;cursor:not-allowed}.development-text{white-space:pre-wrap;overflow-wrap:break-word;line-height:1.7;padding:16px;border:1px solid #b2a4ce;border-radius:12px;background:#eee8fa;color:#273c63}html[data-theme=dark] .player-browse-bar{background:#26334d;border-color:#8e7aae}html[data-theme=dark] .player-browse-bar p{color:#f0eaff!important}html[data-theme=dark] .development-text{background:#2c2845!important;color:#f3edff!important;border-color:#9b89b9!important}html[data-theme=dark] textarea[name=development_goal]{background:#14243b!important;color:#f3edff!important;-webkit-text-fill-color:#f3edff!important;border-color:#899dc2!important}';document.head.appendChild(style);})();

var helpRecoveryActive,helpRecoveryVerified,helpResetUntil=0;
function recoveryError(e){if(e.status===429||/rate_limit|rate limit/i.test((e.code||'')+' '+(e.message||'')))return 'İstek sınırına ulaşıldı. Peş peşe deneme yapma; bir süre sonra tekrar dene. E-posta gelmezse yöneticine bildir.';if(e.code==='same_password')return 'Öncekinden farklı bir şifre belirle.';if(e.code==='weak_password')return 'En az 8 karakterli, daha güçlü bir şifre belirle.';return 'İşlem tamamlanamadı. Bağlantı süresi dolmuş olabilir. Yeni bağlantı iste; sürerse yöneticine bildir. Şifreni paylaşma.';}
function openLoginHelp(){var d=el('login-help-dialog');if(el('email').value)d.querySelector('input').value=el('email').value.trim();if(!d.open)d.showModal();}
function showRecoveryView(){show('reset-view');var root=el('reset-view');root.querySelector('form').hidden=!helpRecoveryVerified;root.querySelector('.recovery-status').textContent=helpRecoveryVerified?'Bağlantı doğrulandı. Yeni uygulama şifreni kendin belirle.':'Bağlantı doğrulanamadı veya süresi dolmuş. Giriş yardımından yeni bağlantı iste.';}
function initLoginHelp(){var hash=new URLSearchParams(location.hash.slice(1));helpRecoveryActive=hash.get('type')==='recovery'||hash.has('error_code');helpRecoveryVerified=false;var b=document.createElement('button');b.type='button';b.className='help-launch';b.textContent='ŞİFREMİ UNUTTUM / GİRİŞ YARDIMI';b.onclick=openLoginHelp;el('login-form').appendChild(b);var d=document.createElement('dialog');d.id='login-help-dialog';d.className='help-card';d.setAttribute('aria-labelledby','login-help-title');d.innerHTML='<h2 id="login-help-title">GİRİŞ YARDIM MERKEZİ</h2><p>Uygulama şifren, e-posta hesabının şifresiyle aynı olmak zorunda değil. Şifreni kimseyle paylaşma.</p><details><summary>İLK KEZ GİRECEĞİM</summary><p>Yöneticinin sana özel davetini aç. 1 · HESAP OLUŞTUR ile bir kez kayıt ol; sonra 2 · GİRİŞ YAP ile gir.</p></details><details><summary>HESAP BAĞLI / DAVET HATASI</summary><p>İlk kayıtta kullandığın e-postayla GİRİŞ YAP. Başka e-postayla yeni hesap açma. Hata sürerse yöneticine e-postanı ve hata mesajını bildir; şifren görünmesin.</p></details><form><h3>ŞİFREMİ UNUTTUM</h3><label>KAYITLI E-POSTAN<input type="email" name="email" autocomplete="email" required placeholder="Hesabını açtığın e-posta"></label><p>Şifre yenileme bağlantısı e-postayla gelir. Normal girişte e-posta veya SMS kodu gerekmez.</p><button type="submit">ŞİFRE YENİLEME BAĞLANTISI İSTE</button><p class="help-status" role="status" aria-live="polite"></p></form><details><summary>E-POSTA GELMEDİ / BAĞLANTI AÇILMADI</summary><p>Gelen kutunu ve spam klasörünü kontrol et. En son gelen bağlantıyı Chrome veya Safari’de aç. Hizmet sınırı varsa tekrar tekrar deneme; yöneticine bildir.</p></details><button type="button" class="help-close">KAPAT</button>';document.body.appendChild(d);d.querySelector('.help-close').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();var f=e.target,b=f.querySelector('button'),status=f.querySelector('.help-status');if(!f.reportValidity())return;if(Date.now()<helpResetUntil){status.textContent='Yeni istek göndermeden önce bir dakika bekle; gelen kutunu ve spam klasörünü kontrol et.';return;}b.disabled=true;status.textContent='İstek gönderiliyor…';helpResetUntil=Date.now()+60000;try{var r=await supabase.auth.resetPasswordForEmail(f.elements.email.value.trim(),{redirectTo:location.origin+location.pathname});if(r.error)throw r.error;status.textContent='Bu adrese kayıtlı hesap varsa yenileme e-postası gönderilir. Gelen kutunu ve spam klasörünü kontrol et. En son gelen bağlantıyı kullan.';}catch(error){status.textContent=recoveryError(error);}finally{b.disabled=false;}};var root=document.createElement('section');root.id='reset-view';root.className='card help-card hidden';root.innerHTML='<h2>YENİ UYGULAMA ŞİFREN</h2><p class="recovery-status" role="status"></p><form hidden><label>YENİ ŞİFRE<input type="password" name="password" autocomplete="new-password" minlength="8" required></label><label>ŞİFREYİ TEKRARLA<input type="password" name="confirm" autocomplete="new-password" minlength="8" required></label><p>En az 8 karakterli bir şifre belirle. Şifreni kimseye gönderme.</p><button type="submit">YENİ ŞİFREMİ KAYDET</button><p class="reset-status" role="status"></p></form><button type="button" class="return-login">GİRİŞ EKRANINA DÖN</button><button type="button" class="reset-help">YENİ BAĞLANTI İSTE / YARDIM</button>';el('login-view').after(root);root.querySelector('.reset-help').onclick=openLoginHelp;root.querySelector('.return-login').onclick=async()=>{if(helpRecoveryVerified)await supabase.auth.signOut({scope:'local'});helpRecoveryActive=false;helpRecoveryVerified=false;root.querySelector('form').reset();history.replaceState(null,'',location.pathname);show('login-view');};root.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!helpRecoveryVerified)return;var f=e.target,status=f.querySelector('.reset-status'),b=f.querySelector('button');if(!f.reportValidity())return;if(f.elements.password.value!==f.elements.confirm.value){status.textContent='İki şifre aynı değil. Tekrar kontrol et.';return;}b.disabled=true;status.textContent='Şifren kaydediliyor…';try{var r=await supabase.auth.updateUser({password:f.elements.password.value});if(r.error)throw r.error;f.reset();helpRecoveryActive=false;helpRecoveryVerified=false;inviteToken='';sessionStorage.removeItem('pending-player-invite');await supabase.auth.signOut();history.replaceState(null,'',location.pathname);show('login-view');el('login-form').querySelector('[data-login-mode=login]').click();loginStatus('Şifren yenilendi. Yeni uygulama şifrenle GİRİŞ YAP.');}catch(error){status.textContent=recoveryError(error);}finally{b.disabled=false;}};supabase.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'&&session){helpRecoveryActive=true;helpRecoveryVerified=true;setTimeout(showRecoveryView,0);}});}
var helpFriendlyBase=friendlyLoginError;friendlyLoginError=function(e){var m=e.message||'';if(/şifresi uyuşmuyor/.test(m))return 'E-posta veya uygulama şifresi uyuşmuyor. Adresini kontrol et. Şifreni hatırlamıyorsan ŞİFREMİ UNUTTUM / GİRİŞ YARDIMI düğmesini kullan.';if(/Bu hesap zaten bağlı|Oyuncunun hesabı zaten bağlı/.test(m))return 'Oyuncu hesabın bağlı. İlk kayıt yaptığın e-postayla GİRİŞ YAP. Doğru e-postayla da olmuyorsa yöneticine bildir; tekrar hesap oluşturma.';if(/yetki kaydı bulunamadı|davet.*eşleşmedi/i.test(m))return 'Hesabın oluşmuş ama oyuncu bağlantın tamamlanmamış. Yeniden kayıt olma; e-postanı yöneticine bildir. Şifreni gönderme.';return helpFriendlyBase(e);};
var missingRequest=0;
function missingRatingRows(players,season){return players.map(p=>({player:p,stats:(p.player_season_stats||[]).find(s=>s.season===season)||{}})).filter(r=>Number(r.stats.matches)>0&&r.stats.manager_rating==null).sort((a,b)=>Number(b.stats.matches)-Number(a.stats.matches)||a.player.full_name.localeCompare(b.player.full_name,'tr'));}
async function openMissingRatings(){var box=el('missing-ratings-panel');if(!box||activeRole!=='admin')return;var token=++missingRequest,season=selectedSeason;box.innerHTML='<h3>EKSİK PUANLAR</h3><p role="status">Kaydedilmiş veriler kontrol ediliyor…</p>';try{var auth=await supabase.rpc('is_admin');if(auth.error||!auth.data)throw Error('Yönetici yetkisi gerekiyor');var players=[];for(var page=0;;page++){var r=await supabase.from('players').select('id,full_name,position,player_season_stats(season,matches,manager_rating)').is('archived_at',null).order('id').range(page*500,page*500+499);if(r.error)throw r.error;players.push(...r.data);if(r.data.length<500)break;}if(token!==missingRequest||season!==selectedSeason)return;var rows=missingRatingRows(players,season);box.innerHTML='<h3>EKSİK VERİ / PUAN KONTROLÜ</h3><p>'+safe(season)+' · Maçı olup genel oyuncu puanı boş olanlar. Girilmiş 0 puan eksik sayılmaz. Maç başına puan değil, mevcut OYUNCU PUANI alanı kontrol edilir.</p><p class="missing-total" role="status">'+rows.length+' OYUNCUNUN PUANI EKSİK</p><label>OYUNCU ARA<input type="search" class="missing-search" placeholder="Ad soyad veya mevki"></label><button type="button" class="missing-refresh">LİSTEYİ YENİLE</button><div class="missing-list"></div>';function draw(){var term=box.querySelector('input').value.trim().toLocaleLowerCase('tr-TR');box.querySelector('.missing-list').innerHTML=rows.filter(r=>(r.player.full_name+' '+(r.player.position||'')).toLocaleLowerCase('tr-TR').includes(term)).map(r=>'<article><h4>'+safe(r.player.full_name)+'</h4><p>'+safe(r.player.position||'MEVKİ YOK')+' · '+Number(r.stats.matches)+' MAÇ · PUAN BEKLENİYOR</p><button type="button" data-missing-player="'+safe(r.player.id)+'">PUAN GİR / OYUNCUYU AÇ</button></article>').join('')||'<p>'+(rows.length?'Aramana uygun oyuncu yok.':'Maçı olup genel puanı boş kalan oyuncu yok.')+'</p>';box.querySelectorAll('[data-missing-player]').forEach(b=>b.onclick=()=>{var id=b.dataset.missingPlayer,f=Array.from(document.querySelectorAll('.player-edit')).find(f=>f.dataset.id===id);if(!f)return;setDashboardPage('roster');stepOpen(id);var input=f.querySelector('.fair-manager-input');if(input){input.scrollIntoView({behavior:'smooth',block:'center'});input.focus({preventScroll:true});}});}box.querySelector('input').oninput=draw;box.querySelector('.missing-refresh').onclick=openMissingRatings;draw();el('dashboard-nav').querySelector('[data-page=missing_ratings]').textContent='EKSİK PUANLAR · '+rows.length;}catch(e){if(token!==missingRequest)return;box.innerHTML='<h3>EKSİK PUANLAR</h3><p role="alert">Liste alınamadı. Bağlantını kontrol edip yeniden dene.</p><button type="button">TEKRAR DENE</button>';box.querySelector('button').onclick=openMissingRatings;}}
var missingAdminBase=loadAdmin;loadAdmin=async function(){await missingAdminBase();var nav=el('dashboard-nav');if(!nav.querySelector('[data-page=missing_ratings]')){var b=document.createElement('button');b.type='button';b.dataset.page='missing_ratings';b.textContent='EKSİK PUANLAR';b.onclick=()=>setDashboardPage('missing_ratings');nav.querySelector('[data-page=statistics]').after(b);}if(!el('missing-ratings-panel')){var box=document.createElement('section');box.id='missing-ratings-panel';box.className='card help-card';box.hidden=true;el('admin-view').appendChild(box);}if(dashboardPage==='missing_ratings')setDashboardPage('missing_ratings');};var missingPageBase=setDashboardPage;setDashboardPage=function(page){missingPageBase(page);var box=el('missing-ratings-panel');if(box)box.hidden=page!=='missing_ratings';if(page==='missing_ratings'){document.querySelector('.admin-heading h2').textContent='EKSİK PUANLAR';openMissingRatings();}};
