function fastPlayerSearch(){if(activeRole!=='admin'||el('admin-view')?.classList.contains('hidden'))return;var d=el('fast-player-dialog');if(!d){d=document.createElement('dialog');d.id='fast-player-dialog';d.className='personal-dialog';document.body.appendChild(d);}d.innerHTML='<header><h2 tabindex="-1">OYUNCU BUL</h2><button type="button" class="fast-close">KAPAT ×</button></header><label>AD / FORMA NUMARASI<input type="search" placeholder="Örn. İhsan" autocomplete="off"></label><p class="fast-count" role="status"></p><div class="fast-results"></div><p class="fast-feedback" role="status"></p>';function draw(){var norm=x=>String(x||'').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i'),q=norm(d.querySelector('input').value.trim()),rows=fastPlayerForms().filter(f=>norm(f.querySelector('[name=full_name]')?.value+' '+f.querySelector('[name=jersey_number]')?.value).includes(q));d.querySelector('.fast-count').textContent=rows.length+' AKTİF OYUNCU';d.querySelector('.fast-results').innerHTML=rows.slice(0,50).map(f=>'<article><h3>'+safe(f.querySelector('[name=full_name]').value)+'</h3><small>FORMA '+safe(f.querySelector('[name=jersey_number]').value||'—')+' · '+safe(f.querySelector('[name=position]').value||'—')+'</small><div class="personal-actions"><button data-fast="profile" data-id="'+safe(f.dataset.id)+'">PROFİL</button><button data-fast="stats" data-id="'+safe(f.dataset.id)+'">İSTATİSTİK</button>'+(staffCan('messages')?'<button data-fast="message" data-id="'+safe(f.dataset.id)+'">MESAJ</button>':'')+'</div></article>').join('')||'<p>Oyuncu bulunamadı. Silinen oyuncular ayrı bölümdedir.</p>';d.querySelectorAll('[data-fast]').forEach(b=>b.onclick=async()=>{var id=b.dataset.id,kind=b.dataset.fast;if(!fastPlayerForms().some(f=>f.dataset.id===id)){d.querySelector('.fast-feedback').textContent='Oyuncu artık aktif listede değil.';return;}d.close();if(kind==='stats'){showPlayerStatistics(id);return;}if(kind==='profile'){simpleActivate(simplePick('roster'));openPlayerEditor(id);return;}if(!staffCan('messages'))return;fastMessageTarget=id;if(!simpleActivate(simplePick('messages')))fastMessageTarget=null;});}d.querySelector('input').oninput=draw;d.querySelector('.fast-close').onclick=()=>d.close();draw();d.showModal();d.querySelector('h2').focus({preventScroll:true});}
