async function mountPrimaryAdmins(){var host=el('staff-panel');if(!host||!staffState?.owner)return;var box=document.createElement('section');box.className='primary-admin-box';host.querySelector('h3').after(box);box.innerHTML='<h3>ANA YÖNETİCİ ATA / KALDIR</h3><p role="status">Kişiler yükleniyor…</p>';try{var r=await supabase.rpc('club_primary_admin',{p_action:'list'});if(r.error)throw r.error;if(!host.isConnected||dashboardPage!=='staff')return;var people=r.data.people||[],uid=r.data.user_id;box.innerHTML='<h3>ANA YÖNETİCİ ATA / KALDIR</h3><p>Seçtiğin kişi tüm alanları kullanabilir, diğer kişilere yetki verebilir ve ana yönetici atayabilir. Kurucu hesabın korunur.</p><label>KİŞİ SEÇ<select class="primary-person"><option value="">Ad soyad seç</option>'+people.map(p=>'<option value="'+safe(p.id)+'">'+safe(p.name)+(p.founder?' · KURUCU':p.primary?' · ANA YÖNETİCİ':p.manager?' · YÖNETİCİ':' · OYUNCU')+'</option>').join('')+'</select></label><div class="primary-person-actions"></div><p class="primary-feedback" role="status"></p>';var select=box.querySelector('select'),out=box.querySelector('.primary-person-actions'),msg=box.querySelector('.primary-feedback');out.innerHTML='<button type="button" disabled>ANA YÖNETİCİ YAP · ÖNCE KİŞİ SEÇ</button>';select.onchange=()=>{msg.textContent='';var p=people.find(x=>x.id===select.value);out.replaceChildren();if(!p){out.innerHTML='<button type="button" disabled>ANA YÖNETİCİ YAP · ÖNCE KİŞİ SEÇ</button>';return;}var info=document.createElement('p');info.textContent=p.founder?'KURUCU · Bu hesabın yetkisi kaldırılamaz.':p.id===uid?'Kendi ana yönetici yetkini buradan değiştiremezsin.':p.primary?'ANA YÖNETİCİ · Tüm alanlar ve yetki dağıtımı açık.':'Ana yönetici değil. Mevcut sınırlı yetkileri ayrı bölümden yönetebilirsin.';out.appendChild(info);if(p.founder||p.id===uid)return;var b=document.createElement('button');b.type='button';b.className=p.primary?'primary-revoke':'primary-grant';b.textContent=p.primary?'ANA YÖNETİCİLİĞİ KALDIR':'ANA YÖNETİCİ YAP';b.onclick=async()=>{var want=!p.primary,warning=want?p.name+' ANA YÖNETİCİ olacak. Tüm verileri yönetebilir, başkalarına yetki verebilir, ana yönetici atayabilir ve kurucu dışındaki ana yöneticilerin yetkisini kaldırabilir. Onaylıyor musun?':p.name+' için ANA YÖNETİCİ yetkisi kaldırılacak. Tüm işlem alanları kapalı başlayacak; istersen alttaki bölümden sınırlı yetki verebilirsin. Onaylıyor musun?';if(!confirm(warning))return;b.disabled=true;msg.textContent='Kaydediliyor…';try{await staffRefresh();if(!staffState?.owner)throw Error('Ana yönetici yetkin değişti.');var q=await supabase.rpc('club_primary_admin',{p_action:'set',p_data:{user_id:p.id,enabled:want,version:p.version}});if(q.error)throw q.error;await openStaffPanel();var feedback=el('staff-panel')?.querySelector('.primary-feedback');if(feedback)feedback.textContent=p.name+(want?' ana yönetici yapıldı.':' için ana yöneticilik kaldırıldı; işlem yetkileri kapatıldı.');}catch(e){msg.textContent='Kaydedilemedi: '+e.message;b.disabled=false;}};out.appendChild(b);};}catch(e){box.innerHTML='<h3>ANA YÖNETİCİ ATA / KALDIR</h3><p role="alert">Liste alınamadı: '+safe(e.message)+'</p>';}}
